-- app_versions 增加 store(分发渠道)维度:同一 platform 下 Google Play / 华为 / 小米 /
-- 应用宝 / 荣耀 / 官网 APK 各自可以有一条 latest。
-- store 可空且默认 NULL ⇒ NULL 就是"加列前的那一格":旧客户端与旧登记腿的行为逐字不变。
-- 不加唯一约束:同渠道多条 history 属正常,"同 platform+store 唯一 latest" 由写侧降级维持。
ALTER TABLE "app_versions" ADD COLUMN IF NOT EXISTS "store" varchar(32);--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "app_versions_platform_store_idx" ON "app_versions" ("platform","store");--> statement-breakpoint
